export type Cell = [x: number, y: number];

const key = ([x, y]: Cell): string => `${x},${y}`;

const neighbors = ([x, y]: Cell): Cell[] => {
  const result: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) result.push([x + dx, y + dy]);
    }
  }
  return result;
};

export const nextGeneration = (cells: Cell[]): Cell[] => {
  const living = new Set(cells.map(key));
  const liveNeighborCount = (cell: Cell): number =>
    neighbors(cell).filter((n) => living.has(key(n))).length;

  const candidates = new Map<string, Cell>();
  for (const cell of cells) {
    for (const candidate of [cell, ...neighbors(cell)]) {
      candidates.set(key(candidate), candidate);
    }
  }

  const isAliveNextGeneration = (cell: Cell): boolean => {
    const liveNeighbors = liveNeighborCount(cell);
    const survives = liveNeighbors === 2 || liveNeighbors === 3;
    const isBorn = liveNeighbors === 3;
    return living.has(key(cell)) ? survives : isBorn;
  };

  return [...candidates.values()].filter(isAliveNextGeneration);
};

